import { useId, useRef, useState, type ComponentProps } from "react";
import { X } from "lucide-react";
import { Button } from "./button";
import { Combobox } from "./combobox";
import type { ComboboxOption } from "./combobox";
import { cn } from "./utils";
import type { EntityReference } from "./work-management-types";

function getReferenceKey(reference: EntityReference) {
    return JSON.stringify([reference.kind, reference.id]);
}

type RelationPickerProps = Omit<
    ComponentProps<"div">,
    "children" | "onChange" | "role" | "aria-label"
> & {
    label: string;
    value: readonly EntityReference[];
    options: readonly EntityReference[];
    onValueChange: (
        value: EntityReference[],
    ) => void | Promise<void>;
    onQueryChange?: (query: string) => void;
    onOpenReference?: (reference: EntityReference) => void;
    loading?: boolean;
    errorMessage?: string | null;
    emptyMessage?: string;
    saveErrorMessage?: string;
    disabled?: boolean;
};

function validateReferences(
    label: string,
    value: readonly EntityReference[],
    options: readonly EntityReference[],
) {
    if (!label.trim()) {
        throw new Error("RelationPicker requires a label.");
    }
    for (const [name, references] of [
        ["value", value], ["options", options],
    ] as const) {
        const keys = new Set<string>();
        for (const reference of references) {
            if (!reference.id.trim() || !reference.title.trim()) {
                throw new Error(
                    `RelationPicker ${name} need nonempty IDs and titles.`,
                );
            }
            const key = getReferenceKey(reference);
            if (keys.has(key)) {
                throw new Error(
                    "RelationPicker " + name + " contain duplicate ID for " +
                    `kind ${reference.kind}: ${reference.id}`,
                );
            }
            keys.add(key);
        }
    }
}

function EntityReferencePreview({
    reference,
    onOpen,
}: {
    reference: EntityReference;
    onOpen?: (reference: EntityReference) => void;
}) {
    const content = (
        <span className="min-w-0">
            <span className="block truncate text-sm font-medium">
                {reference.title}
            </span>
            {(reference.path || reference.description) && (
                <span className="block truncate text-xs text-muted">
                    {reference.path ?? reference.description}
                </span>
            )}
        </span>
    );

    return (
        <div className={
            "flex min-w-0 items-center gap-2 rounded-sm border " +
            "border-border bg-surface px-[var(--space-3)] py-2"
        }>
            <span className={
                "shrink-0 rounded-sm bg-surface-subtle px-2 py-1 " +
                "text-xs text-muted"
            }>
                {reference.kind}
            </span>
            {onOpen ? (
                <button type="button"
                    className={
                        "min-w-0 flex-1 text-left text-foreground " +
                        "hover:underline focus-visible:outline-2 " +
                        "focus-visible:outline-focus"
                    }
                    onClick={() => onOpen(reference)}>
                    {content}
                </button>
            ) : (
                <span className="min-w-0 flex-1 text-foreground">
                    {content}
                </span>
            )}
        </div>
    );
}

function RelationPicker({
    label,
    value,
    options,
    onValueChange,
    onQueryChange,
    onOpenReference,
    loading = false,
    errorMessage = null,
    emptyMessage = "연결할 항목이 없습니다.",
    saveErrorMessage = "관계를 저장하지 못했습니다. 다시 시도하세요.",
    disabled = false,
    className,
    ...props
}: RelationPickerProps) {
    const generatedId = useId();
    const pendingRef = useRef(false);
    const [pendingReferenceKey, setPendingReferenceKey] = useState<
        string | null
    >(null);
    const [saveError, setSaveError] = useState<string | null>(null);
    const selectedKeys = new Set(value.map(getReferenceKey));
    const optionsByKey = new Map(options.map((reference) => [
        getReferenceKey(reference),
        reference,
    ]));

    validateReferences(label, value, options);

    const choices: ComboboxOption[] = options
        .filter((reference) => !selectedKeys.has(getReferenceKey(reference)))
        .map((reference) => ({
            value: getReferenceKey(reference),
            label: reference.title,
            disabled: reference.disabled,
        }));

    async function updateSelection(
        reference: EntityReference,
        selected: boolean,
    ) {
        if (disabled || pendingRef.current || reference.disabled) return;
        const referenceKey = getReferenceKey(reference);
        const isSelected = selectedKeys.has(referenceKey);
        if (selected === isSelected) return;
        const next = selected
            ? [...value, reference]
            : value.filter((item) => getReferenceKey(item) !== referenceKey);

        pendingRef.current = true;
        setPendingReferenceKey(referenceKey);
        setSaveError(null);
        try {
            await onValueChange(next);
        } catch {
            setSaveError(saveErrorMessage);
        } finally {
            pendingRef.current = false;
            setPendingReferenceKey(null);
        }
    }

    return (
        <div {...props} role="group" aria-label={label}
            aria-busy={loading || pendingReferenceKey !== null || undefined}
            className={cn("grid min-w-0 gap-3", className)}>
            <Combobox
                id={`${generatedId}-search`}
                aria-label={`${label} 검색`}
                placeholder="연결할 항목 검색"
                options={choices}
                value={null}
                filterOptions={!onQueryChange}
                loading={loading}
                errorMessage={errorMessage}
                emptyMessage={emptyMessage}
                disabled={disabled || pendingReferenceKey !== null}
                onQueryChange={onQueryChange}
                onValueChange={(key) => {
                    if (key === null) return;
                    const reference = optionsByKey.get(key);
                    if (reference) void updateSelection(reference, true);
                }}
            />
            {value.length === 0 ? (
                <p className="m-0 text-sm text-muted">연결된 항목이 없습니다.</p>
            ) : (
                <ul aria-label={`${label} 연결 항목`}
                    className="m-0 grid list-none gap-2 p-0">
                    {value.map((reference) => (
                        <li key={getReferenceKey(reference)}
                            className="flex min-w-0 gap-2">
                            <div className="min-w-0 flex-1">
                                <EntityReferencePreview
                                    reference={reference}
                                    onOpen={onOpenReference} />
                            </div>
                            <Button type="button" variant="outline" size="icon"
                                aria-label={`${reference.title} 연결 해제`}
                                disabled={disabled ||
                                    pendingReferenceKey !== null ||
                                    reference.disabled}
                                onClick={() => {
                                    void updateSelection(reference, false);
                                }}>
                                {pendingReferenceKey ===
                                    getReferenceKey(reference) ? (
                                    <span className="sr-only">처리 중</span>
                                ) : (
                                    <X aria-hidden="true" className="size-4" />
                                )}
                            </Button>
                        </li>
                    ))}
                </ul>
            )}
            {pendingReferenceKey !== null && (
                <p role="status" className="m-0 text-xs text-muted">
                    관계를 저장하는 중입니다.
                </p>
            )}
            {saveError && (
                <p role="alert" className="m-0 text-sm text-danger">
                    {saveError}
                </p>
            )}
        </div>
    );
}

export { RelationPicker };
export type { RelationPickerProps };
export type {
    EntityReference, EntityReferenceKind,
} from "./work-management-types";
